#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_PAGES 100
#define MAX_BUTTONS 20
#define MAX_HISTORY 1000
#define MAX_LINE 1000

typedef struct {
    int x1, y1, x2, y2;
    int target_page;
} Button;

typedef struct {
    char name[100];
    Button buttons[MAX_BUTTONS];
    int button_count;
} Page;

Page pages[MAX_PAGES];
int page_count = 0;
int history[MAX_HISTORY];
int history_pos = -1;
int history_end = -1;

int find_page(const char *name) {
    for (int i = 0; i < page_count; i++) {
        if (strcmp(pages[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}

void add_page(const char *name) {
    if (find_page(name) == -1) {
        strcpy(pages[page_count].name, name);
        pages[page_count].button_count = 0;
        page_count++;
    }
}

void add_button(const char *page_name, int x1, int y1, int x2, int y2, const char *target) {
    int page_idx = find_page(page_name);
    if (page_idx == -1) {
        add_page(page_name);
        page_idx = find_page(page_name);
    }

    int target_idx = find_page(target);
    if (target_idx == -1) {
        add_page(target);
        target_idx = find_page(target);
    }

    Button *btn = &pages[page_idx].buttons[pages[page_idx].button_count];
    btn->x1 = x1;
    btn->y1 = y1;
    btn->x2 = x2;
    btn->y2 = y2;
    btn->target_page = target_idx;
    pages[page_idx].button_count++;
}

void navigate_to(int page_idx) {
    history_pos++;
    history[history_pos] = page_idx;
    history_end = history_pos;
}

int main() {
    char line[MAX_LINE];
    int current_page = -1;

    // Initialize with home page
    add_page("home");

    while (fgets(line, sizeof(line), stdin)) {
        line[strcspn(line, "\n")] = 0;

        if (strlen(line) == 0) continue;

        if (line[0] == 'P') {
            // Page definition: P page_name
            char page_name[100];
            sscanf(line + 2, "%s", page_name);
            add_page(page_name);

        } else if (line[0] == 'B') {
            // Button definition: B page_name x1 y1 x2 y2 target_page
            char page_name[100], target[100];
            int x1, y1, x2, y2;
            sscanf(line + 2, "%s %d %d %d %d %s", page_name, &x1, &y1, &x2, &y2, target);
            add_button(page_name, x1, y1, x2, y2, target);

        } else if (line[0] == 'C') {
            // Click: C x y
            int x, y;
            sscanf(line + 2, "%d %d", &x, &y);

            if (current_page == -1) {
                current_page = find_page("home");
                navigate_to(current_page);
                printf("%s\n", pages[current_page].name);
                continue;
            }

            Page *page = &pages[current_page];
            int found = 0;

            for (int i = 0; i < page->button_count; i++) {
                Button *btn = &page->buttons[i];
                if (x >= btn->x1 && x <= btn->x2 && y >= btn->y1 && y <= btn->y2) {
                    current_page = btn->target_page;
                    navigate_to(current_page);
                    printf("%s\n", pages[current_page].name);
                    found = 1;
                    break;
                }
            }

            if (!found) {
                printf("none\n");
            }

        } else if (line[0] == 'B' && strlen(line) == 1) {
            // Back: B
            if (history_pos > 0) {
                history_pos--;
                current_page = history[history_pos];
                printf("%s\n", pages[current_page].name);
            } else {
                printf("none\n");
            }

        } else if (line[0] == 'F') {
            // Forward: F
            if (history_pos < history_end) {
                history_pos++;
                current_page = history[history_pos];
                printf("%s\n", pages[current_page].name);
            } else {
                printf("none\n");
            }
        }
    }

    return 0;
}

