static Page pages[MAXN];
static int pageCount = 0;

static int find_page(const char *name) {
    for (int i = 0; i < pageCount; i++) {
        if (strcmp(pages[i].name, name) == 0) return i;
    }
    return -1;
}

static int get_page(const char *name) {
    int id = find_page(name);
    if (id != -1) return id;
    strcpy(pages[pageCount].name, name);
    pages[pageCount].nlinks = 0;
    pages[pageCount].links = NULL;
    return pageCount++;
}

static int in_rect(int x, int y, Link *l) {
    return x >= l->x1 && x <= l->x2 && y >= l->y1 && y <= l->y2;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        char pname[MAXNAME];
        int k;
        scanf("%s %d", pname, &k);
        int pid = get_page(pname);
        pages[pid].nlinks = k;
        pages[pid].links = (Link *)malloc(sizeof(Link) * k);
        for (int j = 0; j < k; j++) {
            char target[MAXNAME];
            scanf("%d %d %d %d %s",
                  &pages[pid].links[j].x1,
                  &pages[pid].links[j].y1,
                  &pages[pid].links[j].x2,
                  &pages[pid].links[j].y2,
                  target);
            pages[pid].links[j].to = get_page(target);
        }
    }

    char start[MAXNAME];
    scanf("%s", start);
    int current = find_page(start);
    if (current == -1) current = get_page(start);

    int q;
    scanf("%d", &q);

    int *back = (int *)malloc(sizeof(int) * (q + 5));
    int *forward = (int *)malloc(sizeof(int) * (q + 5));
