            int moved = 0;
            for (int j = 0; j < pages[current].nlinks; j++) {
                if (in_rect(x, y, &pages[current].links[j])) {
                    back[btop++] = current;
                    current = pages[current].links[j].to;
                    ftop = 0;
                    moved = 1;
                    break;
                }
            }
            (void)moved;
        } else if (strcmp(op, "BACK") == 0) {
            if (btop > 0) {
                forward[ftop++] = current;
                current = back[--btop];
            }
        } else if (strcmp(op, "FORWARD") == 0) {
            if (ftop > 0) {
