public class Solution {
    static class Page {
        String name;
        int[][] buttons; // each button: {x1, y1, x2, y2, targetPage}

        Page(String name, int[][] buttons) {
            this.name = name;
            this.buttons = buttons;
        }

        int getTargetPage(int x, int y) {
            for (int[] button : buttons) {
                if (x >= button[0] && x <= button[2] && 
                    y >= button[1] && y <= button[3]) {
                    return button[4];
                }
            }
            return -1; // no button clicked
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of test cases
        int T = scanner.nextInt();

        for (int t = 0; t < T; t++) {
            // Read number of pages
            int N = scanner.nextInt();
            scanner.nextLine(); // consume newline

            Page[] pages = new Page[N];

            // Read page definitions
            for (int i = 0; i < N; i++) {
                String line = scanner.nextLine().trim();
                String[] parts = line.split(" ");

                String pageName = parts[0];
                int numButtons = Integer.parseInt(parts[1]);

                int[][] buttons = new int[numButtons][5];
                for (int j = 0; j < numButtons; j++) {
                    String[] coords = scanner.nextLine().trim().split(" ");
                    buttons[j][0] = Integer.parseInt(coords[0]); // x1
                    buttons[j][1] = Integer.parseInt(coords[1]); // y1
                    buttons[j][2] = Integer.parseInt(coords[2]); // x2
                    buttons[j][3] = Integer.parseInt(coords[3]); // y2
                    buttons[j][4] = Integer.parseInt(coords[4]); // targetPage
                }

                pages[i] = new Page(pageName, buttons);
            }

            // Read number of operations
            int M = scanner.nextInt();
            scanner.nextLine(); // consume newline

            // Process operations
            List<Integer> history = new ArrayList<>();
            int currentPage = 0;
            int historyIndex = 0;
            history.add(currentPage);

            List<String> output = new ArrayList<>();

            for (int i = 0; i < M; i++) {
                String operation = scanner.nextLine().trim();

                if (operation.equals("BACK")) {
                    if (historyIndex > 0) {
                        historyIndex--;
                        currentPage = history.get(historyIndex);
                    }
                } else if (operation.equals("FORWARD")) {
                    if (historyIndex < history.size() - 1) {
                        historyIndex++;
                        currentPage = history.get(historyIndex);
                    }
                } else if (operation.equals("SHOW")) {
                    output.add(pages[currentPage].name);
                } else {
                    // Click operation: "CLICK x y"
                    String[] parts = operation.split(" ");
                    int x = Integer.parseInt(parts[1]);
                    int y = Integer.parseInt(parts[2]);

                    int targetPage = pages[currentPage].getTargetPage(x, y);
                    if (targetPage != -1 && targetPage < N) {
                        // Remove forward history
                        while (history.size() > historyIndex + 1) {
                            history.remove(history.size() - 1);
                        }
                        history.add(targetPage);
                        historyIndex++;
                        currentPage = targetPage;
                    }
                }
            }

            // Print output for this test case
            for (String s : output) {
                System.out.println(s);
            }
        }

        scanner.close();
    }
}

