public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read pages
        int numPages = sc.nextInt();
        // Map from page name to list of links
        Map<String, List<int[]>> pageLinks = new HashMap<>();
        Map<String, List<String>> pageTargets = new HashMap<>();

        for (int i = 0; i < numPages; i++) {
            String pageName = sc.next();
            int numLinks = sc.nextInt();
            List<int[]> links = new ArrayList<>();
            List<String> targets = new ArrayList<>();
            for (int j = 0; j < numLinks; j++) {
                int x1 = sc.nextInt(), y1 = sc.nextInt();
                int x2 = sc.nextInt(), y2 = sc.nextInt();
                String target = sc.next();
                links.add(new int[]{Math.min(x1,x2), Math.min(y1,y2), Math.max(x1,x2), Math.max(y1,y2)});
                targets.add(target);
            }
            pageLinks.put(pageName, links);
            pageTargets.put(pageName, targets);
        }

        String startPage = sc.next();
        int numOps = sc.nextInt();

        // Browser history: stack-like with current position
        List<String> history = new ArrayList<>();
        history.add(startPage);
        int current = 0;

        StringBuilder sb = new StringBuilder();

        for (int op = 0; op < numOps; op++) {
            String cmd = sc.next();
            if (cmd.equals("CLICK")) {
                int x = sc.nextInt(), y = sc.nextInt();
                String curPage = history.get(current);
                List<int[]> links = pageLinks.get(curPage);
                List<String> targets = pageTargets.get(curPage);
                String dest = null;
                for (int j = 0; j < links.size(); j++) {
                    int[] r = links.get(j);
                    if (x >= r[0] && x <= r[2] && y >= r[1] && y <= r[3]) {
                        dest = targets.get(j);
                        break;
                    }
                }
                if (dest != null) {
                    // Remove forward history
                    while (history.size() > current + 1) {
                        history.remove(history.size() - 1);
                    }
                    history.add(dest);
                    current++;
                }
            } else if (cmd.equals("BACK")) {
                if (current > 0) current--;
            } else if (cmd.equals("FORWARD")) {
                if (current < history.size() - 1) current++;
            } else if (cmd.equals("SHOW")) {
                sb.append(history.get(current)).append("\n");
            }
        }

        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Link {
        int x1, y1, x2, y2;
        String target;

        Link(int x1, int y1, int x2, int y2, String target) {
            this.x1 = Math.min(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.x2 = Math.max(x1, x2);
            this.y2 = Math.max(y1, y2);
            this.target = target;
        }

        boolean contains(int x, int y) {
            return x >= x1 && x <= x2 && y >= y1 && y <= y2;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        Map<String, List<Link>> pages = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String pageName = fs.next();
            int m = fs.nextInt();
            List<Link> list = new ArrayList<>();
            for (int j = 0; j < m; j++) {
                int x1 = fs.nextInt();
                int y1 = fs.nextInt();
                int x2 = fs.nextInt();
                int y2 = fs.nextInt();
                String target = fs.next();
                list.add(new Link(x1, y1, x2, y2, target));
            }
            pages.put(pageName, list);
        }

        String startPage = fs.next();
        int q = fs.nextInt();

        List<String> back = new ArrayList<>();
        List<String> forward = new ArrayList<>();
        String current = startPage;

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String op = fs.next();

            if (op.equals("click")) {
                int x = fs.nextInt();
                int y = fs.nextInt();
                List<Link> links = pages.get(current);
                String nextPage = null;
                if (links != null) {
                    for (Link link : links) {
                        if (link.contains(x, y)) {
                            nextPage = link.target;
                            break;
                        }
                    }
                }
                if (nextPage != null) {
                    back.add(current);
                    current = nextPage;
                    forward.clear();
                }
            } else if (op.equals("back")) {
                if (!back.isEmpty()) {
                    forward.add(current);
                    current = back.remove(back.size() - 1);
                }
            } else if (op.equals("forward")) {
                if (!forward.isEmpty()) {
                    back.add(current);
                    current = forward.remove(forward.size() - 1);
                }
            } else if (op.equals("show")) {
                out.append(current).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

