            } else if (url == "https://example.com/page2") {
                buttons = {
                    {10, 10, 200, 50, "https://example.com"},
                    {10, 70, 200, 110, "https://example.com/page5"}
                };
            } else {
                buttons = {
                    {10, 10, 200, 50, "https://example.com"}
                };
            }
        } else {
            // Default for unknown pages
            pageWidth = 800;
            pageHeight = 600;
            buttons = {
                {10, 10, 200, 50, "https://example.com"}
            };
        }
    }

    // Go back in history
    bool goBack() {
        if (history.empty()) return false;
        forward.push_back(current);
        current = history.back();
        history.pop_back();
        updatePageContent(current);
        return true;
    }

    // Go forward in history
    bool goForward() {
        if (forward.empty()) return false;
        history.push_back(current);
        current = forward.back();
        forward.pop_back();
        updatePageContent(current);
        return true;
    }

    // Click at coordinates, return URL if a button was clicked, else empty string
    string click(int x, int y) {
        for (auto& btn : buttons) {
            int x1 = get<0>(btn), y1 = get<1>(btn);
            int x2 = get<2>(btn), y2 = get<3>(btn);
            if (x >= x1 && x <= x2 && y >= y1 && y <= y2) {
                return get<4>(btn);
            }
        }
        return "";
    }

    // Show current page info
    void show() const {
        cout << "Current page: " << current << "\n";
        cout << "Page size: " << pageWidth << "x" << pageHeight << "\n";
        cout << "Buttons:\n";
        for (auto& btn : buttons) {
            cout << "  (" << get<0>(btn) << "," << get<1>(btn) << ") to ("
                 << get<2>(btn) << "," << get<3>(btn) << ") -> " << get<4>(btn) << "\n";
        }
    }

    // Get visited pages in order (for final output)
    vector<string> visited;
    void recordVisit(const string& url) {
        visited.push_back(url);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    Browser browser;
    int n;
    cin >> n;
    cin.ignore(); // ignore newline after n

    // Record initial page
    browser.recordVisit(browser.current);

    for (int i = 0; i < n; i++) {
        string line;
        getline(cin, line);
        stringstream ss(line);
        string command;
        ss >> command;

        if (command == "click") {
            int x, y;
            ss >> x >> y;
            string url = browser.click(x, y);
            if (!url.empty()) {
                browser.loadPage(url);
                browser.recordVisit(url);
            }
        } else if (command == "back") {
            if (browser.goBack()) {
                browser.recordVisit(browser.current);
            }
        } else if (command == "forward") {
            if (browser.goForward()) {
                browser.recordVisit(browser.current);
            }
        } else if (command == "show") {
            browser.show();
        }
    }

    // Output all visited pages
    cout << "\nVisited pages:\n";
    for (const string& url : browser.visited) {
        cout << url << "\n";
    }

    return 0;
}

