#include <bits/stdc++.h>
using namespace std;

struct Page {
    string url;
    int x1, y1, x2, y2;
    string target;
};

static bool inside(int x, int y, const Page& p) {
    return p.x1 <= x && x <= p.x2 && p.y1 <= y && y <= p.y2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    unordered_map<string, Page> pages;
    for (int i = 0; i < n; ++i) {
        Page p;
        cin >> p.url >> p.x1 >> p.y1 >> p.x2 >> p.y2 >> p.target;
        pages[p.url] = p;
    }

    string home;
    cin >> home;

    int m;
    cin >> m;

    vector<string> backHist;
    vector<string> forwardHist;
    string cur = home;

    for (int i = 0; i < m; ++i) {
        string op;
        cin >> op;

        if (op == "CLICK") {
            int x, y;
            cin >> x >> y;
            auto it = pages.find(cur);
            if (it != pages.end() && inside(x, y, it->second)) {
                backHist.push_back(cur);
                cur = it->second.target;
                forwardHist.clear();
            }
        } else if (op == "BACK") {
            if (!backHist.empty()) {
                forwardHist.push_back(cur);
                cur = backHist.back();
                backHist.pop_back();
            }
        } else if (op == "FORWARD") {
            if (!forwardHist.empty()) {
                backHist.push_back(cur);
                cur = forwardHist.back();
                forwardHist.pop_back();
            }
        } else if (op == "SHOW") {
            cout << cur << '\n';
        }
    }

    return 0;
}
